<?php require_once 'bootstrap.php';$public=true;$pageTitle='Leaderboard';$sob=db()->query("SELECT sr.current_streak,sr.lifetime_days,up.leaderboard_display,up.nickname,u.display_name FROM sobriety_records sr JOIN users u ON u.sic_id=sr.user_sic_id JOIN user_preferences up ON up.user_sic_id=u.sic_id WHERE up.leaderboard_opt_in=1 AND up.leaderboard_display<>'HIDDEN' ORDER BY sr.current_streak DESC LIMIT 100")->fetchAll();$clubs=db()->query("SELECT w.sic_id,w.entity_name,w.country,COALESCE(SUM(CASE WHEN d.rank_eligible=1 AND d.status='POSTED' THEN d.amount ELSE 0 END),0) qdrx FROM dependex_world_registry w LEFT JOIN drx_ledger d ON d.club_sic_id=w.sic_id WHERE w.network_level='LOCAL_CLUB' GROUP BY w.sic_id ORDER BY qdrx DESC,w.entity_name LIMIT 100")->fetchAll();require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Community Impact</span><h1>Leaderboard</h1><p>Il Club può competere sull'impatto. La sobrietà personale resta volontaria e rispettosa.</p></div></section><section class="card"><h2>🌱 Cammino — opt-in</h2><?php if(!$sob):?><p>Nessun partecipante pubblico.</p><?php endif;?><?php foreach($sob as $i=>$r):$name=$r['leaderboard_display']==='ANONYMOUS'?'Anonimo':($r['leaderboard_display']==='NICKNAME'&&$r['nickname']?$r['nickname']:$r['display_name']);?><div class="leader-row"><b><?=$i+1?></b><span><?=h($name)?></span><em><?=number_format((int)$r['current_streak'],0,',','.')?> giorni</em></div><?php endforeach;?></section><section class="card"><h2>🏆 Club DRX</h2><?php foreach($clubs as $i=>$r):?><div class="leader-row"><b><?=$i+1?></b><span><?=h($r['entity_name'])?><small> · <?=h($r['country'])?></small></span><em><?=number_format((float)$r['qdrx'],0,',','.')?> DRX</em></div><?php endforeach;?></section><?php require '_footer.php';?>